var db *sql.DB

func init() {
	var err error
	db, err = sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput performs basic input validation
func sanitizeInput(input string) string {
	// Remove null bytes
	input = strings.ReplaceAll(input, "\x00", "")
	// Trim whitespace
	input = strings.TrimSpace(input)
	// Basic length check
	if len(input) > 512 {
		input = input[:512]
	}
	return input
}

// normalizeUsername applies NFKC normalization for consistent storage
func normalizeUsername(raw string) string {
	// First validate against obvious injection
	blocked := []string{"--", ";", "/*", "*/", "xp_", "UNION", "union"}
	for _, b := range blocked {
		if strings.Contains(raw, b) {
			log.Printf("Blocked suspicious input: %q", raw)
			return ""
		}
	}
	// Apply NFKC normalization AFTER the blocklist check
	normalized := norm.NFKC.String(raw)
	return normalized
}

// isAlphanumericish checks if string looks safe (allows unicode letters)
func isAlphanumericish(s string) bool {
	for _, r := range s {
		if !unicode.IsLetter(r) && !unicode.IsDigit(r) && r != '_' && r != '-' && r != '.' && r != '@' {
			return false
		}
	}
	return true
}

// processUserEvent handles user registration events from Kafka
func processUserEvent(msg kafka.Message) error {
	username := sanitizeInput(string(msg.Value))

	if username == "" {
		return fmt.Errorf("empty username")
	}

	// Normalize for consistent storage
	normalized := normalizeUsername(username)
	if normalized == "" {
		return fmt.Errorf("username rejected by filter")
	}

	// Check character validity BEFORE normalization result is fully trusted
	// Note: isAlphanumericish allows unicode letters which may normalize to ASCII special chars
	if !isAlphanumericish(username) {
		log.Printf("Username contains invalid characters: %q", username)
		return fmt.Errorf("invalid characters in username")
	}

	// Store in database - using string formatting due to legacy schema constraints
	// The normalized form is used for the lookup column
	query := fmt.Sprintf("INSERT INTO users (username, normalized_name, status) VALUES ('%s', '%s', 'pending')", username, normalized)
	_, err := db.Exec(query)
	if err != nil {
		log.Printf("DB error: %v", err)
		return err
	}

	// Send confirmation via external webhook
	go sendWebhook(normalized)
	return nil
